import{_ as t,c as s,o,ah as a}from"./chunks/framework.BX6hejMT.js";const p=JSON.parse('{"title":"Vendored web font of the base map","description":"","frontmatter":{},"headers":[],"relativePath":"playwright/fonts/noto-sans/README.md","filePath":"playwright/fonts/noto-sans/README.md"}'),n={name:"playwright/fonts/noto-sans/README.md"};function r(h,e,d,i,f,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="vendored-web-font-of-the-base-map" tabindex="-1">Vendored web font of the base map <a class="header-anchor" href="#vendored-web-font-of-the-base-map" aria-label="Permalink to &quot;Vendored web font of the base map&quot;">​</a></h1><p><code>@fontsource/noto-sans</code> <strong>5.3.0</strong>: the stylesheets <code>400.css</code> and <code>700.css</code> – the two weights the map styles declare, „Noto Sans Regular“ and „Noto Sans Bold“ – and the woff2 files they name, fetched from <code>https://cdn.jsdelivr.net/npm/@fontsource/noto-sans/</code> on 2026-10-06. Licence: SIL Open Font License 1.1, see <code>LICENSE</code>.</p><p><code>ol-mapbox-style</code> loads this stylesheet from that CDN for the labels of the base map. <code>playwright/vendored-fonts.ts</code> answers the same URLs from this folder instead, so that every capture renders the labels with exactly these files and never waits for the internet - see the comment there for what went wrong without it.</p><p>Only the woff2 files are kept; Chromium never asks for the <code>.woff</code> fallbacks the stylesheet also lists. A request for a file that is not here fails the test, so a stylesheet change in the app shows up as an error, not as a different image.</p><p>The version is pinned on purpose: the unversioned CDN URL serves whatever is latest, and a new release of the font would redraw every label in every map image at a moment nobody chose. Refreshing is a deliberate step, like raising <code>QONNECTRA_REF</code>: fetch the stylesheets, <code>LICENSE</code> and the woff2 files they reference, note the version from the package&#39;s <code>package.json</code> here, regenerate the map images and review them. A weight the styles start to use and that is not here shows up as a failed test naming the missing stylesheet.</p>',5)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
